    # One prompt, four parts in order: engine source, rule sheet, verdicts,
    # schema + output contract, then the ask.
    prompt = (
        INTRO
        + ENGINE_SOURCE
        + PART_B
        + RULE_SHEET
        + PART_C
        + VERDICTS
        + PART_D
        + PLANNER_SCHEMA
        + OUTPUT_CONTRACT
        + ASK
    )
    response = llm.prompt(prompt)
    print("=" * 72)
    print("PLANNER AUTHOR OUTPUT")
    print("=" * 72)
    print(response)
